// Generate the classic browser binding from the authoritative shared team data.
import { readFileSync, writeFileSync } from "node:fs";
const teams = JSON.parse(
  readFileSync(
    new URL("../public/data/nfl-teams.json", import.meta.url),
    "utf8",
  ),
);
writeFileSync(
  new URL("../public/assets/nfl-teams.js", import.meta.url),
  "// Generated by scripts/build-team-data.mjs from public/data/nfl-teams.json.\nconst NFL_TEAM_ABBREVIATIONS = " +
    JSON.stringify(teams, null, 2) +
    ";\n",
);
